import {Port} from '../../core/index.js';
import {THREE,mesh,slab,materials,portQuaternion,ringY,cappedSweep} from './geometry.js';
import {spec} from './dimensions.js';
const tau=Math.PI*2;
export function grove(host){const frame=new THREE.Group();frame.name='NBIoT-CN own blue open-top HY2.0-4P board receiver';frame.position.fromArray(spec.grove.position);frame.quaternion.copy(portQuaternion('bottom'));host.body.add(frame);const blue=materials.plastic(0x059cd1,{roughness:.72}),metal=materials.metal(0xbcb59b),box=(s,p,n,m=blue)=>mesh(frame,new THREE.BoxGeometry(...s),m,p,'NBIoT-CN Grove '+n),rails=[];
 for(const sign of[-1,1]){rails.push(box([.65,6.8,5.2],[sign*4.675,-3.2,0],'full real side wall'));rails.push(box([1.1,6.8,.65],[sign*4.1,-3.2,2.275],'front retaining rail'));box([.7,1.2,.7],[sign*3.85,-1.1,1.95],'mouth shoulder');}
 const floor=box([8.7,6.8,.65],[0,-3.2,-2.275],'physical floor'),rear=box([8.7,.65,4.55],[0,-6.275,-.325],'recessed dielectric back'),bridge=box([3.6,1,.45],[0,-2.3,2.375],'short retaining tongue'),contacts=[],returns=[],tails=[];
 for(let i=0;i<4;i++){const x=(i-1.5)*2;contacts.push(box([.42,5.1,.42],[x,-3.2,.05],'recessed male contact '+(i+1),metal));returns.push(box([.42,2.6,.42],[x,-6.4,.05],'real molded-in contact return '+(i+1),metal));const tail=mesh(host.body,new THREE.CylinderGeometry(.2,.2,2.9,24).rotateX(Math.PI/2),metal,[-x,-24.1,0],'NBIoT-CN actual Grove round solder tail '+(i+1));tails.push(tail);}
 const port=host.add(new Port({id:'grove',label:'PORT.C UART · TXD/RXD/5V/GND',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('bottom'),hitSize:[10,1,5.2],pins:spec.grove.pins.map((name,i)=>({n:i+1,name})),pinGrid:{cols:4,rows:1,pitch:2,center:[0,.05],order:col=>col+1},meta:{role:'visual-connector',face:'bottom',scope:'Four physical contacts/cable pose andown visible labels only;no UART baud timing,AT commands,electrical or cellular behavior.'}}));return{frame,rails,floor,rear,bridge,contacts,returns,tails,port};}
export function sma(host){const frame=new THREE.Group();frame.name='NBIoT-CN own ordinary female SMA andactual gold installation backing';host.body.add(frame);const gold=materials.metal(0xc2aa65,{roughness:.42}),ptfe=materials.plastic(0xe0ddbd,{roughness:.85}),base=mesh(frame,new THREE.CylinderGeometry(3.7,3.7,7.8,48),gold,[0,27.3,0],'NBIoT-CN real rounded gold SMA installation body behindboth native windows'),shaft=ringY(frame,3.09,2.32,8.3,31.2,gold,'NBIoT-CN hollow ordinarySMA threaded outer shaft'),dielectric=ringY(frame,2.31,.65,6.8,32.7,ptfe,'NBIoT-CN physical SMA dielectric with true centre bore'),contact=ringY(frame,.6,.29,5.1,33.1,gold,'NBIoT-CN recessed hollow female centre contact');
 class Thread extends THREE.Curve{getPoint(t,v=new THREE.Vector3()){const a=t*tau*9;return v.set(Math.cos(a)*3.105,31.6+t*7.5,Math.sin(a)*3.105);}}const thread=mesh(frame,cappedSweep(new Thread(),.07,216,8),gold,[0,0,0],'NBIoT-CN visual ordinarySMA external helical thread,non-rated pitch');
 const support=slab(frame,7.6,5.2,.6,.2,[0,24.2,-.3],gold,[],0);support.name='NBIoT-CN actual fixed SMA installation foot';const port=host.add(new Port({id:'antenna',label:'Ordinary SMA female · detachable supplied antenna',connector:spec.sma.connector,position:spec.sma.position,hitSize:[6.35,1,6.35],meta:{role:'visual-connector',face:'top',physicalConnector:'sma-female',scope:'OrdinarySMA geometry only,not RP-SMA. No RF,network,supply or antennaelectrical simulation.'}}));return{frame,base,shaft,dielectric,contact,thread,support,port};}
